const RULES = {
  rangeDays: 10,
  step: 30,
  defaultDuration: 60,
  defaultDays: [1, 2, 3, 4, 5],
  defaultStart: '09:00',
  defaultEnd: '17:00',
};

const norm = v => String(v ?? '').trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
const isActive = v => !['nao', 'n', 'false', '0', 'inativo'].includes(norm(v));
const DAY_MAP = { seg: 1, segunda: 1, ter: 2, terca: 2, qua: 3, quarta: 3, qui: 4, quinta: 4, sex: 5, sexta: 5, sab: 6, sabado: 6, dom: 7, domingo: 7 };

function parseDays(v) {
  const s = norm(v).replace(/-feira/g, '').replace(/\s+a\s+/g, '-');
  if (!s) return [...RULES.defaultDays];
  const out = new Set();
  for (const tok of s.split(/[,;\/\s]+/).filter(Boolean)) {
    const [a, b] = tok.split('-').map(t => DAY_MAP[t] || DAY_MAP[t.slice(0, 3)]);
    if (a && b) { for (let d = a; ; d = d % 7 + 1) { out.add(d); if (d === b) break; } }
    else if (a) out.add(a);
  }
  return out.size ? [...out].sort((x, y) => x - y) : [...RULES.defaultDays];
}

function parseTime(v, fallback) {
  if (v === undefined || v === null || String(v).trim() === '') return parseTime(fallback);
  if (typeof v === 'number') return v < 1 ? Math.round(v * 1440) : Math.round(v * 60);
  const m = String(v).trim().match(/^(\d{1,2})(?:[:h](\d{2})?)?/i);
  return m ? Number(m[1]) * 60 + Number(m[2] || 0) : parseTime(fallback);
}

const hhmm = min => String(Math.floor(min / 60)).padStart(2, '0') + ':' + String(min % 60).padStart(2, '0');

function readBarbers(items) {
  const seen = new Set();
  const list = [];
  for (const it of items) {
    const r = it.json || {};
    const barber = String(r.barber ?? '').trim();
    const calendarId = String(r.calendarId ?? '').trim();
    if (!barber || !calendarId || seen.has(calendarId) || !isActive(r.ativo)) continue;
    seen.add(calendarId);
    const start = parseTime(r.inicio, RULES.defaultStart);
    const end = parseTime(r.fim, RULES.defaultEnd);
    if (end <= start) continue;
    list.push({ barber, calendarId, days: parseDays(r.dias), start, end });
  }
  return list;
}

function readServices(items) {
  const seen = new Set();
  const list = [];
  for (const it of items) {
    const r = it.json || {};
    const name = String(r.servico ?? '').trim();
    if (!name || seen.has(norm(name)) || !isActive(r.ativo)) continue;
    seen.add(norm(name));
    const d = parseInt(String(r.duracao ?? '').replace(/\D/g, ''), 10);
    const duration = d > 0 && d <= 240 ? d : RULES.defaultDuration;
    const price = r.preco === undefined || r.preco === null ? '' : r.preco;
    list.push({ name, duration, price });
  }
  return list;
}

const barbers = readBarbers($('Read Barbers Sheet').all())
  .map(b => ({ name: b.barber, days: b.days, start: hhmm(b.start), end: hhmm(b.end) }));
const services = readServices($input.all());
return [{ json: { status: 'ok', timezone: $now.zoneName, rangeDays: RULES.rangeDays, barbers, services } }];

const RULES = { rangeDays: 10, step: 30, defaultDuration: 60 };
const SHOP_TZ = $now.zoneName;
const body = $input.first().json.body || {};
const barber = String(body.barber || '').trim();
const service = String(body.service || '').trim();
const date = String(body.date || '').trim();
const today = $now.setZone(SHOP_TZ).startOf('day');
const day = DateTime.fromISO(date, { zone: SHOP_TZ });

let message = '';
if (!/^\d{4}-\d{2}-\d{2}$/.test(date) || !day.isValid) message = 'date must be YYYY-MM-DD.';
else if (day < today) message = 'date cannot be in the past.';
else if (day >= today.plus({ days: RULES.rangeDays })) message = 'date must be within ' + RULES.rangeDays + ' days.';

return [{ json: {
  valid: !message, message, barber, service, date, timezone: SHOP_TZ, rules: RULES,
  weekday: day.isValid ? day.weekday : null,
  dayStart: day.isValid ? day.startOf('day').toISO() : null,
  dayEnd: day.isValid ? day.plus({ days: 1 }).startOf('day').toISO() : null,
} }];

