const req = $('Validate Slots Request').first().json;
const ANY = ['', 'any', 'no preference', 'none', 'no', 'sem preferencia'];
const isAny = ANY.includes(norm(req.barber));

const services = readServices($input.all());
const service = services.find(s => norm(s.name) === norm(req.service));
const stop = response => [{ json: { _stop: true, _response: response } }];
if (req.service && !service) return stop({ status: 'service_not_found', message: 'Serviço não encontrado.' });
const duration = service ? service.duration : RULES.defaultDuration;

const all = readBarbers($('Read Barbers for Slots').all());
const chosen = isAny ? all : all.filter(b => norm(b.barber) === norm(req.barber));
if (!chosen.length) return stop({ status: 'barber_not_found', message: 'Barbeiro não encontrado.' });

const working = chosen.filter(b => b.days.includes(req.weekday));
if (!working.length) {
  return stop({ status: 'ok', date: req.date, barber: isAny ? 'any' : chosen[0].barber, duration, dayOff: true, slots: [] });
}
return working.map(b => ({ json: { ...b, isAny, duration, _stop: false } }));

const req = $('Validate Slots Request').first().json;
const step = req.rules.step;
const SHOP_TZ = req.timezone;
const barbers = $('Select Barbers for Day').all().map(i => i.json);
const isAny = barbers[0].isAny;
const duration = barbers[0].duration;
const calSet = new Set(barbers.map(b => b.calendarId));

const busy = {};
const failed = new Set();

let allItems = [];
try {
  allItems = $('Label Event Source').all();
} catch (e) {
  allItems = [];
}

for (const it of allItems) {
  const ev = it.json || {};
  const cal = String(ev.sourceCalendarId || '').trim();
  if (!calSet.has(cal)) continue;
  if (ev.error) { failed.add(cal); continue; }
  if (!ev.start) continue;
  if (String(ev.status || '').toLowerCase() === 'cancelled') continue;
  if (Array.isArray(ev.attendees) && ev.attendees.some(a => a && a.self === true && String(a.responseStatus || '').toLowerCase() === 'declined')) continue;

  const allDay = !ev.start.dateTime;
  const s = allDay ? DateTime.fromISO(ev.start.date, { zone: SHOP_TZ }) : DateTime.fromISO(ev.start.dateTime);
  const endRaw = ev.end ? (ev.end.dateTime || ev.end.date) : null;
  const e = allDay ? DateTime.fromISO(endRaw || ev.start.date, { zone: SHOP_TZ }) : DateTime.fromISO(endRaw || ev.start.dateTime);
  if (!s.isValid || !e.isValid) continue;
  (busy[cal] = busy[cal] || []).push({ start: s.toMillis(), end: Math.max(e.toMillis(), s.toMillis()) });
}

const readable = barbers.filter(b => !failed.has(b.calendarId));
if (!readable.length) {
  return [{ json: { status: 'system_error', message: 'Não foi possível acessar a agenda do Google. Verifique a credencial.' } }];
}

const day = DateTime.fromISO(req.date, { zone: SHOP_TZ });
const nowMs = Date.now();
const first = Math.min(...readable.map(b => b.start));
const last = Math.max(...readable.map(b => b.end));
const slots = [];

for (let m = first; m + duration <= last; m += step) {
  const s = day.set({ hour: Math.floor(m / 60), minute: m % 60, second: 0, millisecond: 0 });
  const e = s.plus({ minutes: duration });
  if (s.toMillis() < nowMs) continue;
  const free = readable
    .filter(b => m >= b.start && m + duration <= b.end)
    .filter(b => !(busy[b.calendarId] || []).some(x => s.toMillis() < x.end && e.toMillis() > x.start))
    .map(b => b.barber);
  if (free.length) {
    slots.push({
      startTime: s.toISO({ suppressMilliseconds: true }),
      endTime: e.toISO({ suppressMilliseconds: true }),
      label: s.toFormat('HH:mm'),
      barbers: free,
    });
  }
}

return [{ json: {
  status: 'ok',
  date: req.date,
  barber: isAny ? 'any' : barbers[0].barber,
  timezone: SHOP_TZ,
  duration,
  calendarReadStatus: readable.length === barbers.length ? 'ok' : 'partial',
  slots,
} }];

const body = $('Book Appointment Webhook').first().json.body || {};
const norm = v => String(v ?? '').trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/\s+/g, ' ');
const rows = $input.all().map(i => i.json);

const found = rows.find(r => norm(r.barber) === norm(body.barber)) || rows[0] || {};
const calendarId = String(found.calendarId || 'primary').trim();
const barberName = found.barber || body.barber || 'Barbeiro';
const clientName = body.name || String(body.summary || '').split('-')[1]?.trim() || 'Cliente';

return [{
  json: {
    calendarId,
    barber: barberName,
    name: clientName,
    service: body.service || 'Corte',
    startTime: body.startTime,
    endTime: body.endTime,
    summary: body.summary || 'Corte Barbearia',
    description: body.description || '',
    number: String(body.number || body.phone_number || '')
  }
}];
